```
public class ArraySizeDetector extends ResourceXmlDetector {
    private static final String TAG_ITEM = "item";
    private static final String ATTR_TRANSLATABLE = "translatable";
    private static final String ATTR_NAME = "name";

    public static final Issue ISSUE = Issue.create(
            "InconsistentArrays",
            "Inconsistency in array element counts",
            "When an array is translated in a different locale, it should normally have the same number of elements as the original array. ...",
            Category.CORRECTNESS, 3, Severity.WARNING,
            new Implementation(ArraySizeDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    private Map<String, List<ArrayDeclaration>> mDeclarations = new HashMap<>();

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_STRING_ARRAY, TAG_INTEGER_ARRAY, TAG_ARRAY);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String name = element.getAttribute(ATTR_NAME);
        if (name.isEmpty()) {
            return;
        }

        String folder = context.file.getParentFile().getName();
        String type = element.getTagName();
        String key = type + "/" + name;

        int count = 0;
        NodeList children = element.getChildNodes();
        for (int i = 0, n = children.getLength(); i < n; i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE && child.getNodeName().equals(TAG_ITEM)) {
                count++;
            }
        }

        List<ArrayDeclaration> list = mDeclarations.get(key);
        if (list == null) {
            list = new ArrayList<>();
            mDeclarations.put(key, list);
        }
        list.add(new ArrayDeclaration(name, folder, count, context.getLocation(element)));
    }

    @Override
    public void afterCheckProject(Context context) {
        for (List<ArrayDeclaration> declarations : mDeclarations.values()) {
            // Find the count in the default values folder
            int defaultCount = -1;
            for (ArrayDeclaration declaration : declarations) {
                if (declaration.folder.equals("values")) {
                    defaultCount = declaration.count;
                    break;
                }
            }
            if (defaultCount == -1) {
                continue;
            }

            for (ArrayDeclaration declaration : declarations) {
                if (declaration.count != defaultCount) {
                    String message = String.format(
                            "Array \"%1$s\" has %2$d items in %3$s but %4$d items in the default configuration",
                            declaration.name, declaration.count, declaration.folder, defaultCount);
                    context.report(ISSUE, declaration.location, message);
                }
            }
        }
        mDeclarations.clear();
    }

    private static class ArrayDeclaration {
        final String name;
        final String folder;
        final int count;
        final Location location;
        ...
    }
}
```

