public class ArraySizeDetector extends ResourceXmlDetector {
    private static final String DEFAULT_VALUES = "values";
    private final Map<String, List<ArrayDeclaration>> mDeclarations = Maps.newHashMap();

    public static final Issue ISSUE = Issue.create(
            "InconsistentArrays",
            "Inconsistency in array element counts",
            "When an array is translated in a different locale, it should normally have the same number of elements as the original array. ...",
            Category.CORRECTNESS, 3, Severity.WARNING,
            new Implementation(ArraySizeDetector.class, Scope.RESOURCE_FILE)
    );

    private static class ArrayDeclaration {
        final String name;
        final String folder;
        final int count;
        final Location location;

        ArrayDeclaration(String name, String folder, int count, Location location) {
            this.name = name;
            this.folder = folder;
            this.count = count;
            this.location = location;
        }
    }

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_STRING_ARRAY, TAG_INTEGER_ARRAY, TAG_ARRAY);
    }

    @Override
    public void beforeCheckProject(@NonNull Context context) {
        if (!context.getDriver().isAnalysisIncremental()) {
            return;
        }

        Project project = context.getProject();
        if (project == null) {
            return;
        }

        List<File> resourceFolders = project.getResourceFolders();
        for (File res : resourceFolders) {
            File[] folders = res.listFiles();
            if (folders == null) {
                continue;
            }
            for (File folder : folders) {
                String folderName = folder.getName();
                if (!folderName.startsWith(FD_RES_VALUES)) {
                    continue;
                }
                File[] files = folder.listFiles();
                if (files == null) {
                    continue;
                }
                for (File file : files) {
                    if (!file.isFile() || !file.getName().endsWith(".xml")) {
                        continue;
                    }
                    addFile(context, file, folderName);
                }
            }
        }
    }

    private void addFile(Context context, File file, String folderName) {
        Document document;
        try {
            document = XmlUtils.parseDocument(file, true);
        } catch (Exception e) {
            // ignore files that don't parse
            return;
        }

        Element root = document.getDocumentElement();
        if (root == null) {
            return;
        }
        NodeList children = root.getChildNodes();
        for (int i = 0, n = children.getLength(); i < n; i++) {
            Node child = children.item(i);
            if (child.getNodeType() != Node.ELEMENT_NODE) {
                continue;
            }
            Element element = (Element) child;
            String tag = element.getTagName();
            if (!TAG_STRING_ARRAY.equals(tag) && !TAG_INTEGER_ARRAY.equals(tag) && !TAG_ARRAY.equals(tag)) {
                continue;
            }
            String name = element.getAttribute(ATTR_NAME);
            if (name.isEmpty()) {
                continue;
            }
            String key = tag + "/" + name;
            int count = 0;
            NodeList items = element.getChildNodes();
            for (int j = 0, m = items.getLength(); j < m; j++) {
                Node item = items.item(j);
                if (item.getNodeType() == Node.ELEMENT_NODE && TAG_ITEM.equals(item.getNodeName())) {
                    count++;
                }
            }
            List<ArrayDeclaration> list = mDeclarations.get(key);
            if (list == null) {
                list = new ArrayList<>();
                mDeclarations.put(key, list);
            }
            list.add(new ArrayDeclaration(name, folderName, count, Location.create(file)));
        }
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String name = element.getAttribute(ATTR_NAME);
        if (name.isEmpty()) {
            return;
        }

        String tag = element.getTagName();
        String key = tag + "/" + name;

        int count = 0;
        NodeList childNodes = element.getChildNodes();
        for (int i = 0, n = childNodes.getLength(); i < n; i++) {
            Node child = childNodes.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE && TAG_ITEM.equals(child.getNodeName())) {
                count++;
            }
        }

        String folder = context.file.getParentFile().getName();

        List<ArrayDeclaration> list = mDeclarations.get(key);
        if (list == null) {
            list = new ArrayList<>();
            mDeclarations.put(key, list);
        }
        list.add(new ArrayDeclaration(name, folder, count, context.getLocation(element)));
    }

    @Override
    public void afterCheckProject(Context context) {
        for (List<ArrayDeclaration> declarations : mDeclarations.values()) {
            int defaultCount = -1;
            for (ArrayDeclaration declaration : declarations) {
                if (DEFAULT_VALUES.equals(declaration.folder)) {
                    defaultCount = declaration.count;
                    break;
                }
            }
            if (defaultCount == -1) {
                continue;
            }

            for (ArrayDeclaration declaration : declarations) {
                if (declaration.count != defaultCount) {
                    String message = String.format(
                            "Array \"%1$s\" has %2$d items in %3$s but %4$d items in the default configuration",
                            declaration.name, declaration.count, declaration.folder, defaultCount);
                    context.report(ISSUE, declaration.location, message);
                }
            }
        }
        mDeclarations.clear();
    }
}
